// Fast path: when the JS billing client asks for JSON, return the print-receipt
// data straight from the payment response (no separate receiptData round-trip).
if (ec.web.requestParameters.wantJson) {
    if (ec.message.hasError()) {
        def _em = ec.message.errorsString; ec.message.clearErrors()
        ec.web.sendJsonResponse([success:false, error:_em])
    } else {
        def _rcpt = null
        try {
            def _r = ec.service.sync().name("zenith.pos.PosServices.get#PosReceiptData").parameter("transactionId", transactionId).call()
            _rcpt = _r?.receipt
        } catch (Throwable _t) { /* receipt build must never fail an already-completed sale */ }
        if (_rcpt && _rcpt.success) {
            ec.web.sendJsonResponse(_rcpt)
        } else {
            // Sale DID complete; we just could not build the receipt here. Report success
            // (so the client never retries/double-charges) and let it fetch the receipt the normal way.
            ec.web.sendJsonResponse([success:true, receiptUnavailable:true, transactionId:transactionId])
        }
    }
}

                def foundProduct = null



                if (cartSearch) {



                    foundProduct = ec.entity.find("mantle.product.Product")



                        .condition("pseudoId", cartSearch).one()



                    if (!foundProduct) {



                        foundProduct = ec.entity.find("mantle.product.Product")



                            .condition("productId", cartSearch).one()



                    }



                    if (!foundProduct) {



                        def cond = ec.entity.conditionFactory.makeCondition("productName",



                            org.moqui.entity.EntityCondition.ComparisonOperator.LIKE, "%" + cartSearch + "%")



                        foundProduct = ec.entity.find("mantle.product.Product")



                            .condition("productTypeEnumId", "PtAsset").condition(cond)



                            .limit(1).one()



                    }



                }

// Fast path: when the JS billing client asks for JSON, return the print-receipt
// data straight from the payment response (no separate receiptData round-trip).
if (ec.web.requestParameters.wantJson) {
    if (ec.message.hasError()) {
        def _em = ec.message.errorsString; ec.message.clearErrors()
        ec.web.sendJsonResponse([success:false, error:_em])
    } else {
        def _rcpt = null
        try {
            def _r = ec.service.sync().name("zenith.pos.PosServices.get#PosReceiptData").parameter("transactionId", transactionId).call()
            _rcpt = _r?.receipt
        } catch (Throwable _t) { /* receipt build must never fail an already-completed sale */ }
        if (_rcpt && _rcpt.success) {
            ec.web.sendJsonResponse(_rcpt)
        } else {
            // Sale DID complete; we just could not build the receipt here. Report success
            // (so the client never retries/double-charges) and let it fetch the receipt the normal way.
            ec.web.sendJsonResponse([success:true, receiptUnavailable:true, transactionId:transactionId])
        }
    }
}

                def results = []



                if (term) {
                    def posOrg = ec.service.sync().name('zenith.barcode.BarcodeServices.get#AuthorizedActiveOrganization').call().activeOrgId
                    // Match in SQL before limiting suggestions, so catalogue order cannot hide a valid code.
                    def products=[]
                    if(posOrg){
                        def cf=ec.entity.conditionFactory;def EC=org.moqui.entity.EntityCondition
                        def like='%'+term.toString().trim().replace('\\','\\\\').replace('%','\\%').replace('_','\\_')+'%'
                        def codes=ec.service.sync().name('zenith.barcode.BarcodeServices.get#ScanAliases').parameters([code:term.toString().trim()]).call().aliases
                        def aliases=ec.entity.find('zenith.erp.barcode.ProductBarcode').condition('organizationPartyId',posOrg).condition('isActive','Y')
                            .condition(cf.makeCondition([cf.makeCondition('barcodeValue',EC.LIKE,like).ignoreCase(),cf.makeCondition('barcodeValue',EC.IN,codes)],EC.OR)).list().collect{it.productId}
                        def parts=['productName','pseudoId','productId'].collect{cf.makeCondition(it,EC.LIKE,like).ignoreCase()}
                        if(aliases)parts.add(cf.makeCondition('productId',EC.IN,aliases))
                        products=ec.entity.find('mantle.product.Product').condition('ownerPartyId',posOrg).condition('productTypeEnumId','PtAsset')
                            .condition(cf.makeCondition(parts,EC.OR)).orderBy('productName').limit(10).list()
                    }
                    products.each { p ->



                        results.add([productId: p.productId, pseudoId: p.pseudoId ?: '',



                                     productName: p.productName ?: p.pseudoId ?: p.productId,



                                     mrpAmount: p.mrpAmount ?: 0])



                    }



                }



                ec.web.sendJsonResponse(results)

def term = (ec.web.parameters.term ?: '').toString().trim()
def termL = term.toLowerCase()
// Scope to the terminal's organization (like the product grid), falling back to the
// user's active org — so it also works for an admin driving a tenant's session.
def sessId = ec.web.parameters.sessionId
def orgId = null
if (sessId) { def s = ec.entity.find("zenith.erp.pos.PosSession").condition("sessionId", sessId).one()
    if (s?.terminalId) orgId = ec.entity.find("zenith.erp.pos.PosTerminal").condition("terminalId", s.terminalId).one()?.organizationPartyId }
if (!orgId || orgId == '_NA_') { def ao = ec.user.getPreference('ACTIVE_ORGANIZATION'); orgId = (ao && ao != '_NA_') ? ao : null }
def out = []
try {
    def rows = ec.entity.find("mantle.party.PartyDetailAndRole")
        .condition("roleTypeId", "in", ['Customer','CustomerBillTo'])
        .condition("ownerPartyId", orgId)
        .orderBy("organizationName,firstName,lastName").limit(1000).list()
    def nameOf = { r -> (r.organizationName ?: (((r.firstName ?: '') + ' ' + (r.lastName ?: '')).trim())) ?: r.partyId }
    def custIdList = rows.collect { it.partyId }.unique()
    // Build partyId -> phone for the org's customers in a few bounded queries (no N+1).
    // Phones live in TelecomNumber (countryCode/areaCode/contactNumber), reached via PartyContactMech.
    def pid2phone = [:]
    if (custIdList) {
        def pcms = ec.entity.find("mantle.party.contact.PartyContactMech").condition("partyId", "in", custIdList)
            .conditionDate("fromDate", "thruDate", ec.user.nowTimestamp).list()
        def cmIds = pcms.collect { it.contactMechId }.unique()
        def cm2num = [:]
        if (cmIds) {
            ec.entity.find("mantle.party.contact.TelecomNumber").condition("contactMechId", "in", cmIds).list().each { tn ->
                cm2num[tn.contactMechId] = ((tn.countryCode ? ('+' + tn.countryCode + ' ') : '') + (tn.areaCode ?: '') + ' ' + (tn.contactNumber ?: '')).replaceAll("\\s+", " ").trim()
            }
        }
        pcms.each { pcm -> def n = cm2num[pcm.contactMechId]; if (n && !pid2phone[pcm.partyId]) pid2phone[pcm.partyId] = n }
    }
    def digits = term.replaceAll("[^0-9]", "")
    def seen = [:] as Map
    for (r in rows) {
        if (seen[r.partyId]) continue
        def nm = nameOf(r)
        def phone = pid2phone[r.partyId] ?: ''
        def phoneDigits = phone.replaceAll("[^0-9]", "")
        def match = !term || nm.toLowerCase().contains(termL) || (r.partyId ?: '').toLowerCase().contains(termL) || (digits.length() >= 3 && phoneDigits.contains(digits))
        if (!match) continue
        seen[r.partyId] = true
        out.add([partyId:r.partyId, name:nm, phone:phone])
        if (out.size() >= 30) break
    }
    ec.web.sendJsonResponse([success:true, customers:out])
} catch (Exception e) { ec.web.sendJsonResponse([success:false, error:e.message, customers:[]]) }

def txId = ec.web.parameters.transactionId
def cpid = ec.web.parameters.customerPartyId
def sid = ec.web.parameters.sessionId
if (!cpid || (!txId && !sid)) { ec.web.sendJsonResponse([success:false, error:'Missing customer or session']); return }
def access = ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess')
    .parameters([transactionId:txId,sessionId:sid,customerPartyId:cpid]).call()
if (!access?.allowed) { ec.web.sendJsonResponse([success:false,error:'Customer or bill unavailable in this organization.']); return }
// Selecting before the first item creates/reuses an unnumbered empty cart.
// The session lock in create#PosTransaction serializes concurrent first-item requests.
if (!txId) {
    def created = ec.service.sync().name('zenith.pos.PosServices.create#PosTransaction').parameter('sessionId',sid).call()
    txId = created?.transactionId
    if (!txId || ec.message.hasError()) { ec.web.sendJsonResponse([success:false,error:'Could not prepare the empty bill.']); return }
}
def txn = ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',txId).forUpdate(true).one()
if (txn.statusId != 'PtCreated') { ec.web.sendJsonResponse([success:false,error:'This bill is already finalized']); return }
def registration = ec.service.sync().name('zenith.tax.TaxServices.get#PartyTaxRegistration').parameter('partyId',cpid).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse([success:false,error:'Customer tax registration is unavailable.']); return }
def destination = registration?.regionGeoId ?: txn.originRegionGeoId
def currentDestination = txn.destinationRegionGeoId ?: txn.originRegionGeoId
boolean hasContents = txn.transactionNumber || ((txn.paidAmount ?: 0) > 0) ||
    ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId',txId).count() > 0 ||
    ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId',txId).count() > 0
if (destination != currentDestination && hasContents) {
    ec.web.sendJsonResponse([success:false,error:'Choose a different tax destination before adding items or taking payment. Start a new bill to change it.']); return
}
def details = ec.entity.find('mantle.party.PartyDetailAndRole').condition('partyId',cpid).limit(1).list()
def person = details ? details[0] : null
def name = person?.organizationName ?: (((person?.firstName ?: '')+' '+(person?.lastName ?: '')).trim()) ?: cpid
def phone = null
def mechanisms = ec.entity.find('mantle.party.contact.PartyContactMech').condition('partyId',cpid)
    .conditionDate('fromDate','thruDate',ec.user.nowTimestamp).list()
for (mechanism in mechanisms) {
    def number = ec.entity.find('mantle.party.contact.TelecomNumber').condition('contactMechId',mechanism.contactMechId).one()
    if (number) { phone = ((number.countryCode ? ('+'+number.countryCode+' ') : '')+(number.areaCode ?: '')+' '+(number.contactNumber ?: '')).replaceAll('\\s+',' ').trim(); if (phone) break }
}
def gstin = registration?.registrationNumber
ec.service.sync().name('update#zenith.erp.pos.PosTransaction').parameters([
    transactionId:txId,customerPartyId:cpid,customerName:name,customerPhone:phone,
    customerGstin:gstin,customerTaxRegNumber:gstin,destinationRegionGeoId:destination]).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse([success:false,error:'Customer could not be changed.']); return }
ec.web.sendJsonResponse([success:true,transactionId:txId,customer:name,customerPhone:phone ?: '',customerPartyId:cpid,customerGstin:gstin ?: ''])

def txId = ec.web.parameters.transactionId
if (!txId) { ec.web.sendJsonResponse([success:false,error:'Missing bill']); return }
def access = ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').parameter('transactionId',txId).call()
if (!access?.allowed) { ec.web.sendJsonResponse([success:false,error:'Bill unavailable in this organization.']); return }
def txn = ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',txId).forUpdate(true).one()
if (txn.statusId != 'PtCreated') { ec.web.sendJsonResponse([success:false,error:'This bill is already finalized']); return }
boolean hasContents = txn.transactionNumber || ((txn.paidAmount ?: 0) > 0) ||
    ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId',txId).count() > 0 ||
    ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId',txId).count() > 0
if ((txn.destinationRegionGeoId ?: txn.originRegionGeoId) != txn.originRegionGeoId && hasContents) {
    ec.web.sendJsonResponse([success:false,error:'Start a new bill to clear a customer with a different tax destination. Existing bill amounts are preserved.']); return
}
txn.customerPartyId = null; txn.customerName = null; txn.customerPhone = null
txn.customerGstin = null; txn.customerTaxRegNumber = null; txn.destinationRegionGeoId = txn.originRegionGeoId; txn.update()
ec.web.sendJsonResponse([success:true,customer:'',customerPhone:'',customerPartyId:''])

def access = ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').call()
if (!access?.allowed || ec.web.parameters.organizationPartyId != access.organizationPartyId) {
    throw new org.moqui.context.ArtifactAuthorizationException('Select the authorized organization before recovering offline sales.')
}
def candidates
try { candidates = new groovy.json.JsonSlurper().parseText(ec.web.parameters.candidates ?: '[]') }
catch (Exception ignored) { ec.web.response.setStatus(400); ec.web.sendJsonResponse([eligibleIds:[]]); return }
if (!(candidates instanceof List) || candidates.size() > 200) {
    ec.web.response.setStatus(400); ec.web.sendJsonResponse([eligibleIds:[]]); return
}
def eligible = []
for (candidate in candidates) {
    if (!(candidate instanceof Map) || !(candidate.offlineId instanceof String) || !candidate.offlineId || candidate.offlineId.length() > 255 ||
        !(candidate.sessionId instanceof String) || !(candidate.terminalId instanceof String)) continue
    if (candidate.organizationPartyId && candidate.organizationPartyId != access.organizationPartyId) continue
    def session = ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',candidate.sessionId)
        .condition('organizationPartyId',access.organizationPartyId).one()
    def terminal = ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',candidate.terminalId)
        .condition('organizationPartyId',access.organizationPartyId).one()
    // one() may resolve by primary key; compare stored ownership explicitly.
    if (session?.organizationPartyId == access.organizationPartyId && terminal?.organizationPartyId == access.organizationPartyId &&
        session.terminalId == terminal.terminalId) eligible.add(candidate.offlineId)
}
ec.web.sendJsonResponse([organizationPartyId:access.organizationPartyId,eligibleIds:eligible.unique()])

                def p = ec.web.parameters



                def action = p.action



                def sessionId = p.sessionId



                def transactionId = p.transactionId



                def taxOn = p.taxOn ?: 'N'



                def result = [success:false]



                try {



                    if (transactionId && ['addItem','setItemMode','updateQty','updatePrice','applyDiscount','removeItem','scanAdd'].contains(action)) {
                        def editable=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',transactionId).forUpdate(true).one()
                        if (!editable || editable.statusId!='PtCreated') { ec.web.sendJsonResponse([success:false,error:'Only an open cart can be edited. Use the audited amendment flow for an issued bill.']);return }
                    }
                    if (action == 'addItem') {



                        def productId = p.productId



                        def unitPrice = p.unitPrice && (p.unitPrice as BigDecimal) != BigDecimal.ZERO ? (p.unitPrice as BigDecimal) : BigDecimal.ZERO


                        if (unitPrice == BigDecimal.ZERO && productId) {


                            def prod = ec.entity.find("mantle.product.Product").condition("productId", productId).one()


                            if (prod?.mrpAmount) unitPrice = prod.mrpAmount as BigDecimal


                            if (unitPrice == BigDecimal.ZERO) {


                                def pp = ec.entity.find("mantle.product.ProductPrice").condition("productId", productId).condition("priceTypeEnumId", "PptList").orderBy("-lastUpdatedStamp").limit(1).one()


                                if (!pp) pp = ec.entity.find("mantle.product.ProductPrice").condition("productId", productId).condition("priceTypeEnumId", "PptCurrent").orderBy("-lastUpdatedStamp").limit(1).one()


                                if (pp?.price) unitPrice = pp.price as BigDecimal


                            }


                        }



                        def addQty = p.addQty ? (p.addQty as BigDecimal) : BigDecimal.ONE



                        if (!transactionId) {



                            def tOut = ec.service.sync().name("zenith.pos.PosServices.create#PosTransaction")



                                .parameters([sessionId:sessionId]).call()



                            transactionId = tOut.transactionId



                        }



                        ec.service.sync().name("zenith.pos.PosServices.add#PosTransactionItem")



                            .parameters([transactionId:transactionId, productId:productId,



                                quantity:addQty, unitPrice:unitPrice, discountPercent:(p.salesModeId ? (ec.entity.find("zenith.erp.pos.PosSalesMode").condition("salesModeId", p.salesModeId).one()?.discountPercent ?: 0) : 0), salesModeId:p.salesModeId, taxOn:taxOn]).call()

                        // Explicit per-mode pricing may block the add (no price set) -> surface it so the client rolls back.
                        if (ec.message.hasError()) { def _em = ec.message.errorsString; ec.message.clearErrors(); ec.web.sendJsonResponse([success:false, error:_em, transactionId:transactionId]); return }

                        if (taxOn == 'N') {



                            def lastItems = ec.entity.find("zenith.erp.pos.PosTransactionItem")



                                .condition("transactionId", transactionId).orderBy("-itemSeqId").list()



                            if (lastItems) {



                                def la = lastItems[0]



                                ec.service.sync().name("update#zenith.erp.pos.PosTransactionItem")



                                    .parameters([transactionId:transactionId, itemSeqId:la.itemSeqId,



                                        totalTaxAmount:0, lineTotal:la.taxableAmount]).call()



                                ec.service.sync().name("zenith.pos.PosServices.recalculate#TransactionTotals")



                                    .parameters([transactionId:transactionId]).call()



                            }



                        }



                    } else if (action == 'setItemMode') {
                        ec.service.sync().name("zenith.pos.PosServices.set#PosTransactionItemMode")
                            .parameters([transactionId:transactionId, itemSeqId:p.itemSeqId, salesModeId:p.itemMode, taxOn:p.taxOn]).call()
                        if (ec.message.hasError()) { def _em = ec.message.errorsString; ec.message.clearErrors(); ec.web.sendJsonResponse([success:false, error:_em, transactionId:transactionId]); return }
                        // An explicit per-line mode choice takes manual control: don't let quantity-break auto-override it.
                        ec.service.sync().name("update#zenith.erp.pos.PosTransactionItem")
                            .parameters([transactionId:transactionId, itemSeqId:p.itemSeqId, manualPrice:'Y']).call()
                    } else if (action == 'updateQty') {



                        def item = ec.entity.find("zenith.erp.pos.PosTransactionItem")



                            .condition("transactionId", transactionId).condition("itemSeqId", p.itemSeqId).one()



                        if (item) {



                            def nq = null
                            try { nq = new BigDecimal((p.newQty ?: '').toString()) } catch (Exception ignored) {}
                            if (nq==null || nq<=0) { ec.web.sendJsonResponse([success:false,error:'Quantity must be greater than zero. Use Remove to delete a line.']);return }



                            if (nq <= 0) {



                                ec.service.sync().name("zenith.pos.PosServices.remove#PosTransactionItem")



                                    .parameters([transactionId:transactionId, itemSeqId:p.itemSeqId]).call()



                            } else {



                                def ls = nq * (item.unitPrice as BigDecimal)



                                def da = ls * ((item.discountPercent ?: 0) as BigDecimal) / 100



                                def ta = ls - da



                                def taxR = BigDecimal.ZERO



                                if (taxOn != 'N' && item.totalTaxAmount != null && item.taxableAmount != null && (item.taxableAmount as BigDecimal) != 0) {



                                    taxR = (item.totalTaxAmount as BigDecimal) / (item.taxableAmount as BigDecimal)



                                }



                                def tt = ta * taxR



                                def lt = ta + tt



                                ec.service.sync().name("update#zenith.erp.pos.PosTransactionItem")



                                    .parameters([transactionId:transactionId, itemSeqId:p.itemSeqId,



                                        quantity:nq, discountAmount:da, taxableAmount:ta,



                                        totalTaxAmount:tt, lineTotal:lt]).call()



                            }



                            ec.service.sync().name("zenith.pos.PosServices.recalculate#TransactionTotals")



                                .parameters([transactionId:transactionId]).call()

                            // Quantity-break: re-evaluate this line's retail/wholesale mode for the new quantity.
                            ec.service.sync().name("zenith.pos.PosServices.applyQuantityBreak#Line")
                                .parameters([transactionId:transactionId, itemSeqId:p.itemSeqId, taxOn:taxOn, cartModeId:salesModeId]).call()

                        }



                    } else if (action == 'updatePrice') {



                        def item = ec.entity.find("zenith.erp.pos.PosTransactionItem")



                            .condition("transactionId", transactionId).condition("itemSeqId", p.itemSeqId).one()



                        if (item) {



                            def np = null
                            try { np = new BigDecimal((p.newPrice ?: '').toString()) } catch (Exception ignored) {}
                            if (np==null || np<0) { ec.web.sendJsonResponse([success:false,error:'Enter a non-negative price.']);return }



                            def q = (item.quantity ?: 1) as BigDecimal



                            def ls = q * np



                            def da = ls * ((item.discountPercent ?: 0) as BigDecimal) / 100



                            def ta = ls - da



                            def taxR = BigDecimal.ZERO



                            if (taxOn != 'N' && item.totalTaxAmount != null && item.taxableAmount != null && (item.taxableAmount as BigDecimal) != 0) {



                                taxR = (item.totalTaxAmount as BigDecimal) / (item.taxableAmount as BigDecimal)



                            }



                            def tt = ta * taxR



                            def lt = ta + tt



                            ec.service.sync().name("update#zenith.erp.pos.PosTransactionItem")



                                .parameters([transactionId:transactionId, itemSeqId:p.itemSeqId,



                                    unitPrice:np, discountAmount:da, taxableAmount:ta,



                                    totalTaxAmount:tt, lineTotal:lt, manualPrice:'Y']).call()



                            ec.service.sync().name("zenith.pos.PosServices.recalculate#TransactionTotals")



                                .parameters([transactionId:transactionId]).call()



                        }



                    } else if (action == 'applyDiscount') {
                        def dTxId = transactionId ?: p.transactionId
                        def dTxn = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", dTxId).one()
                        if (!dTxn || dTxn.statusId != 'PtCreated') { ec.web.sendJsonResponse([success:false, error:'No open bill to discount']); return }
                        def dItems = ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("transactionId", dTxId).orderBy("itemSeqId").list()
                        if (!dItems) { ec.web.sendJsonResponse([success:false, error:'Add items before applying a discount']); return }
                        def dTermId = null
                        def dSess = sessionId ? ec.entity.find("zenith.erp.pos.PosSession").condition("sessionId", sessionId).one() : null
                        if (dSess) dTermId = dSess.terminalId
                        def dTerm = dTermId ? ec.entity.find("zenith.erp.pos.PosTerminal").condition("terminalId", dTermId).one() : null
                        // Discount config is stored per-organization as UserPreference key/values
                        // (POS_DISC_LIMIT / POS_DISC_PIN / POS_DISC_ROUNDSTEP), set from the POS settings.
                        def dOrg = dTerm?.organizationPartyId
                        def dCfg = { k -> dOrg ? ec.entity.find("moqui.security.UserPreference").condition("userId", dOrg).condition("preferenceKey", k).one()?.preferenceValue : null }
                        def _lim = dCfg('POS_DISC_LIMIT'); def dLimit = (_lim != null && _lim.toString().trim() != '') ? new BigDecimal(_lim.toString().trim()) : null
                        def dPin = dCfg('POS_DISC_PIN')
                        def _step = dCfg('POS_DISC_ROUNDSTEP'); def dStep = (_step != null && _step.toString().trim() != '') ? new BigDecimal(_step.toString().trim()) : BigDecimal.ZERO
                        def lineMap = [:]
                        if (p.lineDiscounts) { try { lineMap = new groovy.json.JsonSlurper().parseText(p.lineDiscounts) } catch (Exception _e) { lineMap = [:] } }
                        // intended per-line discount amounts
                        def grossTotal = BigDecimal.ZERO
                        def lineCalc = [:]
                        dItems.each { itm ->
                            def sub = ((itm.quantity ?: 0) as BigDecimal) * ((itm.unitPrice ?: 0) as BigDecimal)
                            grossTotal += sub
                            def dAmt = BigDecimal.ZERO
                            def ld = lineMap[itm.itemSeqId]
                            if (ld) { def v = ((ld.v ?: 0) as BigDecimal); dAmt = (ld.t == 'amt') ? v : (sub * v / 100) }
                            if (dAmt < 0) dAmt = BigDecimal.ZERO
                            if (dAmt > sub) dAmt = sub
                            lineCalc[itm.itemSeqId] = [sub:sub, disc:dAmt]
                        }
                        // whole-bill discount, apportioned across lines on their after-line-discount base
                        def afterLine = grossTotal - (lineCalc.values().sum { it.disc } ?: BigDecimal.ZERO)
                        def billVal = (p.billDiscValue ?: 0) as BigDecimal
                        if (billVal > 0 && afterLine > 0) {
                            def billDisc = (p.billDiscType == 'amt') ? billVal : (afterLine * billVal / 100)
                            if (billDisc > afterLine) billDisc = afterLine
                            dItems.each { itm -> def lc = lineCalc[itm.itemSeqId]; def base = lc.sub - lc.disc
                                lc.disc = lc.disc + (afterLine != 0 ? (billDisc * base / afterLine) : BigDecimal.ZERO)
                                if (lc.disc > lc.sub) lc.disc = lc.sub }
                        }
                        // manager-PIN gate on the effective overall discount %
                        def totalDisc = lineCalc.values().sum { it.disc } ?: BigDecimal.ZERO
                        def effPct = grossTotal > 0 ? (totalDisc * 100 / grossTotal) : BigDecimal.ZERO
                        if (dLimit != null && effPct > dLimit) {
                            if (!dPin || (p.managerPin ?: '') != dPin) {
                                ec.web.sendJsonResponse([success:false, needPin:true, error:'Manager PIN required for a discount above ' + dLimit + '%'])
                                return
                            }
                        }
                        // apply: rewrite each line's discount + recompute tax (GST rate preserved)
                        dItems.each { itm ->
                            def lc = lineCalc[itm.itemSeqId]; def sub = lc.sub; def dAmt = lc.disc
                            def ta = sub - dAmt
