                                .condition("transactionId", txId).orderBy("-itemSeqId").list()
                            def maxSeq = 0
                            existingItems.each { def s = it.itemSeqId ? (it.itemSeqId as int) : 0; if (s > maxSeq) maxSeq = s }
                            def newSeqId = String.format("%05d", maxSeq + 1)
                            _addedSeqId = newSeqId
                            invAdjProduct = productId; invAdjQty = BigDecimal.ZERO - addQty
                            def ls = addQty * unitPrice
                            // Match the added line to THIS bill's tax state. A bill billed with tax
                            // toggled OFF carries zero tax on every existing line, so an item added
                            // during an edit must stay tax-free too — otherwise editing a non-tax bill
                            // silently re-introduces GST (the reported bug). A bill that carries tax
                            // (e.g. MARUTHI) still resolves the product's GST exactly like a live sale.
                            // Empty bill (all lines removed) → default to tax-on, matching a fresh sale.
                            def _billHasTax = true
                            if (existingItems) {
                                _billHasTax = false
                                for (exItm in existingItems) { if (((exItm.totalTaxAmount ?: 0) as BigDecimal) > 0) { _billHasTax = true; break } }
                            }
                            // Resolve GST the same way a live sale does: prefer the product's gstSlabId
                            // (MARUTHI's products), fall back to taxCategoryId (demo/legacy). Both hold an
                            // IndiaGstSlab PK (e.g. GST_18). The entity is zenith.erp.india.IndiaGstSlab.
                            def taxCatId = prod.gstSlabId ?: (prod.taxCategoryId ?: '')
                            def taxAmt = BigDecimal.ZERO
                            def gstRate = BigDecimal.ZERO
                            if (_billHasTax && taxCatId) {
                                def slab = ec.entity.find("zenith.erp.india.IndiaGstSlab").condition("gstSlabId", taxCatId).one()
                                if (slab) { gstRate = (slab.gstRate ?: 0) as BigDecimal; taxAmt = ls * gstRate / 100 }
                            }
                            def lineTotal = ls + taxAmt
                            ec.service.sync().name("create#zenith.erp.pos.PosTransactionItem")
                                .parameters([transactionId:txId, itemSeqId:newSeqId, productId:productId,
                                    productName:prod.productName ?: productId, quantity:addQty,
                                    unitPrice:unitPrice, taxableAmount:ls, totalTaxAmount:taxAmt,
                                    lineTotal:lineTotal, discountPercent:0, discountAmount:0]).call()
                            ec.service.sync().name("zenith.pos.PosServices.recalculate#TransactionTotals")
                                .parameters([transactionId:txId]).call()
                            def txnAfter = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", txId).one()
                            ec.service.sync().name("create#zenith.erp.pos.PosTransactionAmendment")
                                .parameters([transactionId:txId,
                                    amendedByPartyId:ec.user.userAccount?.partyId ?: '',
                                    amendmentDate:ec.user.nowTimestamp, reason:reason,
                                    changeType:'ITEM_ADDED', itemSeqId:newSeqId,
                                    productId:productId, productName:prod.productName ?: productId,
                                    oldValue:'N/A', newValue:(prod.productName ?: productId)+' x'+addQty+' @'+unitPrice,
                                    oldGrandTotal:oldGrand, newGrandTotal:txnAfter.grandTotal ?: 0]).call()
                        }
                        if (['QTY_CHANGE','PRICE_CHANGE'].contains(editType)) {
                            def changedLine=ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId',txId).condition('itemSeqId',itemSeqId).one()
                            def details=ec.entity.find('zenith.erp.tax.TaxLineDetail').condition('referenceType','PosTransactionItem').condition('referenceId',txId).condition('referenceSeqId',itemSeqId).list()
                            details.each { detail -> detail.taxableAmount=changedLine.taxableAmount;detail.taxAmount=((changedLine.taxableAmount ?: 0) as BigDecimal)*((detail.taxRate ?: 0) as BigDecimal)/100;detail.update() }
                        }
                        def txnFinal = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", txId).one()
                        def itemsFinal = ec.entity.find("zenith.erp.pos.PosTransactionItem")
                            .condition("transactionId", txId).orderBy("itemSeqId").list()
                        // Keep the linked Sales invoice consistent with the amended bill so revenue/GST reports stay correct.
                        // Rebuilt in-place (same transaction) because the amended items are not yet committed for a force-new sync.
                        if (txnFinal?.linkedInvoiceId) {
                            def _iid = txnFinal.linkedInvoiceId
                            def _inv = ec.entity.find("mantle.account.invoice.Invoice").condition("invoiceId", _iid).one()
                            if (_inv) {
                                _inv.statusId = "InvoiceInProcess"; _inv.update()
                                ec.entity.find("zenith.erp.tax.TaxLineDetail").condition("referenceType","InvoiceItem").condition("referenceId",_iid).deleteAll()
                                ec.entity.find("mantle.account.invoice.InvoiceItem").condition("invoiceId",_iid).deleteAll()
                                for (li in itemsFinal) {
                                    def _ii = ec.service.sync().name("mantle.account.InvoiceServices.create#InvoiceItem").parameters([
                                        invoiceId:_iid, itemTypeEnumId:"ItemProduct", productId:li.productId,
                                        description:li.productName, quantity:li.quantity, amount:li.unitPrice]).call()
                                    ec.service.sync().name("update#mantle.account.invoice.InvoiceItem").parameters([
                                        invoiceId:_iid, invoiceItemSeqId:_ii.invoiceItemSeqId, productTaxCode:li.productTaxCode,
                                        taxableAmount:li.taxableAmount, totalTaxAmount:li.totalTaxAmount, discountAmount:li.discountAmount]).call()
                                    def _tlds = ec.entity.find("zenith.erp.tax.TaxLineDetail").condition("referenceType","PosTransactionItem")
                                                  .condition("referenceId",txId).condition("referenceSeqId",li.itemSeqId).orderBy("sequenceNum").list()
                                    if (_tlds) {
                                        def _bds = _tlds.collect { [taxAuthorityId:it.taxAuthorityId, taxRateId:it.taxRateId, taxCategoryId:it.taxCategoryId,
                                            taxName:it.taxName, taxRate:it.taxRate, taxableAmount:it.taxableAmount, taxAmount:it.taxAmount,
                                            isIncludedInPrice:it.isIncludedInPrice, countryGeoId:it.countryGeoId, regionGeoId:it.regionGeoId] }
                                        ec.service.sync().name("zenith.tax.TaxServices.store#TaxLineDetails").parameters([
                                            referenceType:"InvoiceItem", referenceId:_iid, referenceSeqId:_ii.invoiceItemSeqId,
                                            parentReferenceType:"Invoice", parentReferenceId:_iid, currencyUomId:"INR", taxBreakdowns:_bds]).call()
                                    }
                                }
                                def _inv2 = ec.entity.find("mantle.account.invoice.Invoice").condition("invoiceId", _iid).one()
                                _inv2.invoiceTotal = txnFinal.grandTotal
                                _inv2.unpaidTotal = ((txnFinal.grandTotal ?: 0) as BigDecimal) - ((_inv2.appliedPaymentsTotal ?: 0) as BigDecimal)
                                _inv2.totalTaxableAmount = txnFinal.subtotal
                                _inv2.totalTaxAmount = txnFinal.totalTaxAmount
                                _inv2.roundOffAmount = txnFinal.roundOff
                                _inv2.statusId = "InvoiceFinalized"
                                _inv2.update()
                            }
                        }
                        // Adjust stock by the edit delta (return to / take from stock) -- tracked products only
                        if (invAdjProduct && invAdjQty != BigDecimal.ZERO) {
                            def _pT = ec.entity.find("mantle.product.Product").condition("productId", invAdjProduct).one()
                            if (_pT?.inventoryTracked == 'Y') {
                                try {
                                    ec.service.sync().name("zenith.inventory.InventoryStockServices.adjust#AssetOnHand").parameters([
                                        organizationPartyId: txnFinal.organizationPartyId, productId: invAdjProduct,
                                        quantityDiff: invAdjQty, reason: ('Bill edit ' + (txnFinal.transactionNumber ?: txId))]).call()
                                } catch (Throwable e) { ec.logger.error("Bill-edit stock adjust failed: " + e.message) }
                            }
                        }
                        // Payment reconciliation: refund (paid > new total) or extra collection (new total > paid)
                        def _paid = (txnFinal.paidAmount ?: 0) as BigDecimal
                        def _pay = (txnFinal.payableAmount ?: 0) as BigDecimal
                        def _refundDue = BigDecimal.ZERO; def _balanceDue = BigDecimal.ZERO
                        if (_paid > _pay) { _refundDue = _paid - _pay } else if (_pay > _paid) { _balanceDue = _pay - _paid }
                        ec.service.sync().name("update#zenith.erp.pos.PosTransaction").parameters([transactionId:txId, changeAmount:_refundDue]).call()
                        def paymentsFinal = ec.entity.find("zenith.erp.pos.PosPayment")
                            .condition("transactionId", txId).list()
                        def amendsFinal = ec.entity.find("zenith.erp.pos.PosTransactionAmendment")
                            .condition("transactionId", txId).orderBy("-amendmentDate").list()
                        result = [success:true, action:'amendBill',
                            bill:[txId:txId, billNo:txnFinal.transactionNumber ?: txId,
                                grand:txnFinal.grandTotal ?: 0, payable:txnFinal.payableAmount ?: 0,
                                refundDue:_refundDue, balanceDue:_balanceDue, newSeq:_addedSeqId,
                                subtotal:txnFinal.subtotal ?: 0, tax:txnFinal.totalTaxAmount ?: 0,
                                items:itemsFinal.collect { [seq:it.itemSeqId, pid:it.productId,
                                    name:it.productName ?: it.productId, qty:it.quantity ?: 0,
                                    price:it.unitPrice ?: 0, tax:it.totalTaxAmount ?: 0, total:it.lineTotal ?: 0] },
                                payments:paymentsFinal.collect { [method:it.paymentMethod ?: '', amount:it.amount ?: 0] },
                                amendments:amendsFinal.collect { [date:ec.l10n.format(it.amendmentDate, 'dd/MM hh:mm a'),
                                    type:it.changeType ?: '', reason:it.reason ?: '',
                                    product:it.productName ?: '', oldVal:it.oldValue ?: '', newVal:it.newValue ?: ''] }
                            ]]
                        ec.web.sendJsonResponse(result)
                        return
                    } else if (action == 'listHeld') {
                        def heldList = ec.entity.find("zenith.erp.pos.PosHeldTransaction")
                            .condition("sessionId", sessionId).condition("statusId", "PhHeld")
                            .orderBy("-holdTime").list()
                        def heldResult = []
                        def heldTotal = 0 as BigDecimal
                        heldList.each { ht ->
                            def itemsList = []
                            def htTotal = (ht.subtotal ?: 0) as BigDecimal
                            heldTotal += htTotal
                            if (ht.itemsJson) {
                                try {
                                    def parsed = new groovy.json.JsonSlurper().parseText(ht.itemsJson)
                                    if (parsed instanceof List) {
                                        parsed.each { pi ->
                                            itemsList.add([name: pi.productName ?: pi.productId ?: '', qty: pi.quantity ?: 0])
                                        }
                                    }
                                } catch (Exception ignored) {}
                            }
                            def custName = ''
                            if (ht.customerPartyId) {
                                def cp = ec.entity.find("mantle.party.Person").condition("partyId", ht.customerPartyId).one()
                                if (cp) custName = [(cp.firstName ?: ''), (cp.lastName ?: '')].findAll{it}.join(' ')
                            }
                            heldResult.add([heldId: ht.heldId, subtotal: htTotal,
                                holdTime: ec.l10n.format(ht.holdTime, 'hh:mm a'),
                                reason: ht.holdReason ?: '', customer: custName ?: 'Walk-In',
                                itemCount: itemsList.size(), items: itemsList])
                        }
                        result = [success:true, action:'listHeld', held:heldResult, heldCount:heldList.size(), heldTotal:heldTotal]
                        ec.web.sendJsonResponse(result)
                        return
                    } else if (action == 'sessionSummary') {



                        def sess = ec.entity.find("zenith.erp.pos.PosSession").condition("sessionId", sessionId).one()



                        if (!sess || sess.statusId != 'PsOpen') {



                            result = [success:false, error:'Session is not open']



                            ec.web.sendJsonResponse(result)



                            return



                        }



                        def txns = ec.entity.find("zenith.erp.pos.PosTransaction")



                            .condition("sessionId", sessionId).condition("statusId", "PtCompleted").list()



                        def txnIds = txns*.transactionId



                        def totalSales = 0 as BigDecimal



                        def cashReceived = 0 as BigDecimal



                        def cardReceived = 0 as BigDecimal



                        def upiReceived = 0 as BigDecimal



                        def changeGiven = 0 as BigDecimal



                        txns.each { totalSales += (it.grandTotal ?: 0) as BigDecimal; changeGiven += (it.changeAmount ?: 0) as BigDecimal }



                        if (txnIds) {



                            def payments = ec.entity.find("zenith.erp.pos.PosPayment").condition("transactionId", "in", txnIds).list()



                            payments.each {



                                def amt = (it.amount ?: 0) as BigDecimal



                                if (it.paymentMethod == 'Cash') cashReceived += amt



                                else if (it.paymentMethod == 'Card') cardReceived += amt



                                else if (it.paymentMethod == 'UPI') upiReceived += amt



                            }



                        }



                        def openingCash = (sess.openingCash ?: 0) as BigDecimal



                        def drawer = ec.service.sync().name("zenith.pos.PosServices.get#PosSessionCashSummary").parameter("sessionId",sess.sessionId).call()
                        def expectedCash = drawer.expectedCash



                        result = [success:true, action:'sessionSummary',



                            billCount:txns.size(), totalSales:totalSales,



                            openingCash:openingCash, cashReceived:drawer.cashReceived,



                            cardReceived:cardReceived, upiReceived:upiReceived,



                            changeGiven:drawer.changeGiven, expectedCash:expectedCash]



                        ec.web.sendJsonResponse(result)



                        return



                    }



                    def txn = transactionId ? ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", transactionId).one() : null



                    def items = transactionId ? ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("transactionId", transactionId).orderBy("itemSeqId").list() : []



                    def totalQty = 0; items.each { totalQty += (it.quantity ?: 0) }



                    result = [success:true, transactionId:transactionId ?: '', txnNum:txn?.transactionNumber ?: '',



                        items: items.collect { [seq:it.itemSeqId, pid:it.productId, name:it.productName ?: it.productId,



                            qty:it.quantity ?: 0, price:it.unitPrice ?: 0, total:it.lineTotal ?: 0,



                            tax:it.totalTaxAmount ?: 0, disc:it.discountPercent ?: 0, mode:(it.salesModeId ?: ''), uom:(it.uomId ? (["OTH_ea":'Nos',"WT_g":'g',"WT_kg":'kg',"VLIQ_ml":'ml',"VLIQ_L":'L',"LEN_m":'m',"LEN_cm":'cm'].get(it.uomId) ?: '') : '')] },



                        sub:txn?.subtotal ?: 0, tax:txn?.totalTaxAmount ?: 0, disc:txn?.discountTotal ?: 0,



                        grand:txn?.grandTotal ?: 0, pay:txn?.payableAmount ?: 0, round:txn?.roundOff ?: 0,
                        customer:txn?.customerName ?: '', customerPhone:txn?.customerPhone ?: '', customerPartyId:txn?.customerPartyId ?: '',



                        cnt:items.size(), tQty:totalQty, modes:(ec.entity.find("zenith.erp.pos.PosSalesMode").condition("isActive","Y").orderBy("isDefault,modeName").list().collect{[id:it.salesModeId, name:it.modeName, disc:(it.discountPercent ?: 0)]})]



                } catch (Exception e) {



                    result = [success:false, error:e.message]



                }



                ec.web.sendJsonResponse(result)

else.script:
ec.entity.find("zenith.erp.pos.PosTransaction").condition("sessionId", sessionId).condition("statusId", "PtCreated").list().each { st ->
    ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("transactionId", st.transactionId).deleteAll()
    ec.entity.find("zenith.erp.pos.PosPayment").condition("transactionId", st.transactionId).deleteAll()
    ec.entity.find("zenith.erp.pos.PosItemPriceOverride").condition("transactionId", st.transactionId).deleteAll()
    try { st.delete() } catch (Exception e) { st.statusId = 'PtVoided'; st.update() }
}

actions.script:
            gridProducts = []



            if (searchTerm) {
                def stLower = searchTerm.toLowerCase()
                def allProds = ec.entity.find("mantle.product.Product")
                    .condition([productTypeEnumId:'PtAsset', ownerPartyId: posOrg])
                    .orderBy("productName").limit(3000).list()
                gridProducts = allProds.findAll { pr ->
                    (pr.productName ?: '').toLowerCase().contains(stLower) ||
                    (pr.pseudoId ?: '').toLowerCase().contains(stLower) ||
                    (pr.productId ?: '').toLowerCase().contains(stLower)
                }
                if (gridProducts.size() > 300) gridProducts = gridProducts.subList(0, 300)



            } else if (catId) {



                def members = ec.entity.find("mantle.product.category.ProductCategoryMember")



                    .condition("productCategoryId", catId)



                    .conditionDate("fromDate", "thruDate", ec.user.nowTimestamp)



                    .orderBy("sequenceNum,productId").list()



                def pIds = members.collect { it.productId }



                if (pIds) {



                    gridProducts = ec.entity.find("mantle.product.Product")



                        .condition("productId", org.moqui.entity.EntityCondition.ComparisonOperator.IN, pIds)



                        .condition([ownerPartyId: posOrg])



                        .limit(3000).orderBy("productName").list()



                }



            } else {



                gridProducts = ec.entity.find("mantle.product.Product")



                    .condition([productTypeEnumId:'PtAsset', ownerPartyId: posOrg])



                    .limit(3000).orderBy("productName").list()



            }







            // Show the live Pricing-module price on grid cards when this shop uses price lists (else the product MRP).
            // No-op (one count query) for shops without price lists, so the POS stays fast and unchanged.
            def _hasPL = ec.entity.find("zenith.erp.pricing.PriceList").condition("organizationPartyId", posOrg).condition("priceListTypeEnumId","PltSelling").count() != 0
            if (_hasPL && gridProducts) {
                for (gp in gridProducts) {
                    try {
                        def _pr = ec.service.sync().name("zenith.pricing.PricingServices.calculate#Price").parameters([productId:gp.productId, quantity:1, organizationPartyId:posOrg, salesChannelEnumId:"ScPos"]).call()
                        if (_pr?.unitPrice != null && (_pr.unitPrice as BigDecimal).signum() == 1) gp.mrpAmount = _pr.unitPrice
                    } catch (Throwable e) { }
                }
            }
            lastBillNo = '-'



            lastBillAmt = '0'



            if (sessionId) {



                def lastBill = ec.entity.find("zenith.erp.pos.PosTransaction")



                    .condition("sessionId", sessionId).condition("statusId", "PtCompleted")



                    .orderBy("-entryDate").limit(1).one()



                if (lastBill) {



                    lastBillNo = lastBill.transactionNumber ?: lastBill.transactionId



                    lastBillAmt = zinr.inr(ec.l10n.format(lastBill.payableAmount ?: 0, '#,##0.00'))



                }



            }







            cartQty = BigDecimal.ZERO



            if (cartItems) {



                cartQty = cartItems.sum { (it.quantity ?: 0) as BigDecimal } ?: BigDecimal.ZERO



            }



            cartAmt = txn?.payableAmount ?: BigDecimal.ZERO



            cartDisc = txn?.discountTotal ?: BigDecimal.ZERO







            heldTxns = []



            if (sessionId) {



                heldTxns = ec.entity.find("zenith.erp.pos.PosHeldTransaction")



                    .condition("sessionId", sessionId).condition("statusId", "PhHeld")



                    .orderBy("holdTime").list()



            }

            // Enriched held-bill list for the server-rendered picker (works in /qapps without JS).
            heldList = []
            def _hi = 0
            for (ht in (heldTxns ?: [])) {
                _hi++
                def cnt = 0
                try { cnt = new groovy.json.JsonSlurper().parseText(ht.itemsJson ?: '[]').size() } catch (Exception e) { cnt = 0 }
                heldList.add([ heldId: ht.heldId, num: _hi, subtotal: (ht.subtotal ?: 0),
                               itemCount: cnt, timeStr: ec.l10n.format(ht.holdTime, 'hh:mm a'),
                               reason: (ht.holdReason ?: '') ])
            }





            dispDate = ec.l10n.format(ec.user.nowTimestamp, 'dd-MM-yyyy')



            dispTime = ec.l10n.format(ec.user.nowTimestamp, 'hh:mm:ss a')







            salesMode = 'RETAIL'



            salesModeColor = '#2e7d32'



            salesModesList = []



            try {



                def allModes = ec.entity.find("zenith.erp.pos.PosSalesMode").condition("isActive", "Y").orderBy("isDefault,modeName").list()



                salesModesList = allModes



                def currentMode = null



                if (salesModeId) {



                    currentMode = allModes.find { it.salesModeId == salesModeId }



                }



                if (!currentMode) {



                    currentMode = allModes.find { it.isDefault == 'Y' }



                }



                if (!currentMode && allModes) {



                    currentMode = allModes[0]



                }



                if (currentMode) {



                    salesMode = currentMode.modeName ?: 'RETAIL'



                    salesModeId = currentMode.salesModeId



                    salesModeColor = currentMode.colorCode ?: '#2e7d32'
                    if (transactionId) {
                        def _txm = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionId", transactionId).one()
                        if (_txm != null && _txm.salesModeId != currentMode.salesModeId) {
                            ec.service.sync().name("zenith.pos.PosServices.reprice#PosTransaction").parameters([transactionId:transactionId, discountPercent:(currentMode.discountPercent ?: 0), salesModeId:currentMode.salesModeId, taxOn:taxOn]).call()
                            if (ec.message.hasError()) {
                                // A cart line has no price in the requested mode -> keep the current mode and tell the cashier.
                                modeSwitchError = ec.message.errorsString; ec.message.clearErrors()
                                def _prev = allModes.find { it.salesModeId == _txm.salesModeId }
                                if (_prev) { currentMode = _prev; salesMode = _prev.modeName ?: 'RETAIL'; salesModeId = _prev.salesModeId; salesModeColor = _prev.colorCode ?: '#2e7d32' }
                            } else {
                                ec.service.sync().name("update#zenith.erp.pos.PosTransaction").parameters([transactionId:transactionId, salesModeId:currentMode.salesModeId]).call()
                            }
                        }
                    }



                }



                // Per-mode grid pricing: the active mode's price per card + a blocked flag
                // for products with no price in a fixed-price mode (so the card can be disabled).
                gridModePrice = [:]; gridModeBlocked = [:]
                def _fx = currentMode != null && currentMode.priceSource == 'PpsFixedProduct'
                if (gridProducts) {
                    if (_fx) {
                        def _gids = gridProducts.collect { it.productId }
                        def _pmap = [:]
                        if (_gids) ec.entity.find("zenith.erp.pos.PosProductModePrice").condition("salesModeId", currentMode.salesModeId).condition("productId", "in", _gids).list().each { _pmap[it.productId] = it.price }
                        gridProducts.each { gp -> def _pp = _pmap[gp.productId]; gridModePrice[gp.productId] = _pp; gridModeBlocked[gp.productId] = (_pp == null) }
                    } else {
                        gridProducts.each { gp -> gridModePrice[gp.productId] = gp.mrpAmount; gridModeBlocked[gp.productId] = false }
                    }
                }
            } catch (Exception e) { /* PosSalesMode may not exist yet */ }

            // ZE-POS-0201: mirror the ZenithApp posOnly role gate so the header can HIDE the back-office
            // affordances a POS-only cashier can't reach — Inventory (ITEM/CATALOGUE) and the Dashboard/App
            // links all bounce straight back here. Sole Zenith role ZENITH_CASHIER, and not the super-admin.
            posOnlyUser = false
            try {
                if (!ec.user.isInGroup("ADMIN")) {
                    def _zrp = (ec.user.userGroupIdSet ?: []).findAll { it?.startsWith("ZENITH_") && it != "ZENITH_ALL" }
                    posOnlyUser = (_zrp.size() == 1 && _zrp.contains("ZENITH_CASHIER"))
                }
            } catch (Exception e) { posOnlyUser = false }

busySessionLinks = []
(terminalList ?: []).findAll { _blockedTerms.contains(it.terminalId) }.each { term ->
    def matching = ec.entity.find('zenith.erp.pos.PosSession')
        .condition('organizationPartyId', posOrg ?: '__NO_ORGANIZATION__')
        .condition('terminalId', term.terminalId).condition('statusId', 'PsOpen').list()
        .find { s -> ec.entity.find('zenith.erp.pos.PosTransaction')
            .condition('sessionId', s.sessionId).condition('statusId', 'PtCompleted').count() > 0 }
    if (matching) busySessionLinks.add([terminalName:term.terminalName ?: term.terminalId,
        sessionId:matching.sessionId])
}
